import gzip, numpy as np, time
from numba import njit, uint64
seqs=[]; names=[]; name=None; parts=[]
for line in open('inputs/read.proportions.q1.fa'):
    line=line.strip()
    if line.startswith('>'):
        if name is not None: names.append(name); seqs.append(''.join(parts).upper())
        name=line[1:].split()[0]; parts=[]
    elif line: parts.append(line)
if name is not None: names.append(name); seqs.append(''.join(parts).upper())
comp=str.maketrans('ACGTN','TGCAN'); mp={'A':0,'C':1,'G':2,'T':3}
def enc(s):
    a=0; b=0
    for i,ch in enumerate(s):
        v=mp.get(ch,0)
        if i<32: a |= v << (2*i)
        else: b |= v << (2*(i-32))
    return a,b
K=36; k1=[]; k2=[]; kc=[]
for ci,s in enumerate(seqs):
    for i in range(len(s)-K+1):
        sub=s[i:i+K]
        a,b=enc(sub); k1.append(a); k2.append(b); kc.append(ci)
        rc=sub.translate(comp)[::-1]
        a,b=enc(rc); k1.append(a); k2.append(b); kc.append(ci)
counts={}
with gzip.open('inputs/read.proportions.q1.fq.gz','rt') as f:
    while True:
        h=f.readline()
        if not h: break
        s=f.readline().strip().upper(); f.readline(); f.readline()
        counts[s]=counts.get(s,0)+1
reads=list(counts); rcnt=np.array([counts[s] for s in reads], dtype=np.int64)
r1=[]; r2=[]
for s in reads:
    a,b=enc(s); r1.append(a); r2.append(b)
k1=np.array(k1,dtype=np.uint64); k2=np.array(k2,dtype=np.uint64); kc=np.array(kc,dtype=np.int64)
r1=np.array(r1,dtype=np.uint64); r2=np.array(r2,dtype=np.uint64)
@njit
def popcount64u(x):
    c=0
    one=np.uint64(1)
    zero=np.uint64(0)
    while x "'!= zero:
        x = x & (x - one)
        c += 1
    return c
@njit
def calc(r1,r2,k1,k2,kc):
    n=r1.shape[0]; m=k1.shape[0]
    min_d=np.empty((n,4),np.int16); min_c=np.zeros((n,4),np.int32)
    mask1=np.uint64(0x5555555555555555); mask2=np.uint64(0x55); one=np.uint64(1)
    for i in range(n):
        for c in range(4): min_d[i,c]=100
        for j in range(m):
            x=r1[i]''^k1[j]
            y=(x | (x >> one)) & mask1
            d=popcount64u(y)
            x2=r2[i]''^k2[j]
            y2=(x2 | (x2 >> one)) & mask2
            d += popcount64u(y2)
            c=kc[j]
            if d < min_d[i,c]: min_d[i,c]=d; min_c[i,c]=1
            elif d == min_d[i,c]: min_c[i,c]+=1
    return min_d,min_c
print('"'names',names,'unique',len(reads),'kmers',len(k1))
